library(tidyverse)

genera <- read_tsv("C:/Users/issea/Downloads/trainset19_072023.rdp/trainset19_072023.rdp/trainset19_072023.rdp.tax",
         col_names = c("accession","taxonomy")) |>
  mutate(taxonomy = stringi::stri_replace_all_regex(taxonomy,";$",""))
fasta_data <- scan("C:/Users/issea/Downloads/trainset19_072023.rdp/trainset19_072023.rdp/trainset19_072023.rdp.fasta",
     sep = "\n", what = character(), quiet = TRUE)

sequence_names <- fasta_data[seq(1,length(fasta_data),by = 2)] |>
  str_replace_all(pattern = "^>([^\t]*)\t.*","\\1")

sequences <- fasta_data[seq(2,length(fasta_data),by = 2)]

seq_table <- tibble(accession = sequence_names, sequence = sequences) |>
  inner_join(genera, by = "accession")
db <- build_kmer_database(seq_table$sequence,seq_table$taxonomy,kmer_size = 8)

profvis::profvis(
  db <- build_kmer_database(seq_table$sequence,seq_table$taxonomy,kmer_size = 8)
)
microbenchmark::microbenchmark(times = 3,
               db <- build_kmer_database(seq_table$sequence,seq_table$taxonomy,kmer_size = 8))
